#include <stdio.h>

void item() { printf("Item Used\n"); }
void map()  { printf("Map Opened\n"); }
void save() { printf("Game Saved\n"); }

int main() {
    int choice = 1;

    // Jump Table: Array of functions
    void (*actions[3])() = {item, map, save};

    if (choice >= 0 && choice < 3) {
        actions[choice](); // Direct jump
    }

    return 0;
}
